class Main {
    static class Box {
        // 공유값과 개인값은 다른 칸이에요.
        static int shared;
        int own;
        Box(int value) { own = value; }
    }

    public static void main(String[] args) {
        // 이번 실험의 시작값이에요.
        int n = 3;
        Box.shared = n;
        Box a = new Box(n);
        Box b = new Box(n + 1);
        // a의 개인 칸만 두 배로 바꿔요.
        a.shared *= 2;
        System.out.println(a.own + Box.shared);
        System.out.println(b.own + Box.shared);
    }
}
